function beadUpdateHUD(){const s=document.getElementById('beadStatus');if(s&&_bead)s.textContent=_bead.status||'';}
function beadZoomAt(x,y,factor){const canvas=document.getElementById('beadCanvas'),g=_bead;if(!canvas||!g)return;const m=beadCanvasMetrics(g,canvas),old=m.view.scale,scale=Math.max(1,Math.min(14,old*factor)),wx=(x-m.w/2-m.view.panX)/old,wy=(y-m.h/2-m.view.panY)/old;m.view.scale=scale;m.view.panX=x-m.w/2-wx*scale;m.view.panY=y-m.h/2-wy*scale;beadClampView(m);beadDraw();}
function beadViewZoom(factor){const canvas=document.getElementById('beadCanvas');if(!canvas)return;const r=canvas.getBoundingClientRect();beadZoomAt(r.width/2,r.height/2,factor);}
function beadFit(){if(!_bead)return;_beadView={id:_bead.id,scale:1,panX:0,panY:0};beadDraw();}

async function beadClear(){if(!_bead)return;if(beadTotal(_bead)&&typeof uiConfirm==='function'&&!await uiConfirm('移除当前图片和图纸？'))return;_bead.target=beadBlank(_bead.cols*_bead.rows);_bead.sourceTarget=beadBlank(_bead.target.length);_bead.board=beadBlank(_bead.target.length);_bead.owners=beadBlank(_bead.target.length);_bead.background=beadBlank(_bead.target.length);_bead.includeBackground=false;_bead.template='upload';_bead.sourceName='';_bead.selected='';_bead.status='图片已移除，请重新上传图片。';beadSave(_bead);render();}
function beadZoom(v){beadViewZoom(Number(v)>=1?1.2:.84);}
function beadLock(){
  const g=_bead,total=g&&beadTotal(g);if(!g||g.phase!=='design')return;if(g.template!=='image'||!g.sourceName){toast('请先上传图片，再开始拼图');return;}if(total<4){toast('图纸至少要有 4 个目标格');return;}g.board=beadBlank(g.target.length);g.owners=beadBlank(g.target.length);g.phase='play';g.turn='me';g.turnPlaced=0;g.round=1;g.busy=false;g.ready=false;g.history=[];g.roleLine='';g.status='图纸已经锁定，轮到你先填 '+beadTurnQuota(g)+' 格。';beadAddHistory(g,'sys','图纸锁定，共 '+total+' 个目标格；每人每轮 '+beadTurnQuota(g)+' 格。');beadSave(g);render();
}
async function beadReturnDesign(){if(!_bead||_bead.busy)return;if(_bead.phase==='play'&&beadFilled(_bead)&&typeof uiConfirm==='function'&&!await uiConfirm('返回设计会清空当前填格进度，继续吗？'))return;if(_bead.archivedView){_bead.archivedView=false;_bead.archiveId='';_bead.completedAt=0;_bead.workName='';_bead.id='bead_'+uid();}_bead.phase='design';_bead.board=beadBlank(_bead.target.length);_bead.owners=beadBlank(_bead.target.length);_bead.turn='me';_bead.turnPlaced=0;_bead.busy=false;_bead.ready=false;_bead.status='图纸已解锁，可以继续修改。';beadSave(_bead);render();}

function beadParsePlan(raw){
  let obj={};try{obj=parseObj(String(raw||''))||{};}catch(_){const s=String(raw||''),focus=(s.match(/(?:focus|颜色)["'：:\s]+([^,"'\n}]+)/i)||[])[1],region=(s.match(/(?:region|区域)["'：:\s]+([^,"'\n}]+)/i)||[])[1],say=(s.match(/(?:say|话)["'：:\s]+([^"'\n}]+)/i)||[])[1];obj={focus,region,say};}
  const rawFocus=String(obj.focus||obj.color||obj.颜色||''),color=BEAD_COLORS.find(x=>rawFocus.includes(x.name)||rawFocus.toLowerCase()===x.id.toLowerCase()),regions=['左上','右上','左下','右下','中央','边缘','任意'],region=regions.find(x=>String(obj.region||obj.区域||'').includes(x))||'任意';let say=String(obj.say||obj.话||'');try{say=cleanReply(say);}catch(_){}say=say.replace(/[\[\]【】{}]/g,'').replace(/\s+/g,' ').trim().slice(0,90);return{color:color&&color.id||'',region,say};
}
function beadRegionScore(g,i,region){const x=i%g.cols,y=Math.floor(i/g.cols),nx=x/(g.cols-1||1),ny=y/(g.rows-1||1);if(region==='左上')return nx+ny;if(region==='右上')return(1-nx)+ny;if(region==='左下')return nx+(1-ny);if(region==='右下')return(1-nx)+(1-ny);if(region==='中央')return Math.abs(nx-.5)+Math.abs(ny-.5);if(region==='边缘')return Math.min(nx,ny,1-nx,1-ny);return i/(g.cols*g.rows);}
function beadRoleCandidates(g){const all=[];for(let i=0;i<g.target.length;i++)if(g.target[i]&&!g.board[i])all.push(i);const foreground=all.filter(i=>!(g.background&&g.background[i]));return foreground.length?foreground:all;}
function beadChooseRoleCells(g,plan){const ids=beadRoleCandidates(g);ids.sort((a,b)=>{const ca=plan.color&&g.target[a]===plan.color?0:1,cb=plan.color&&g.target[b]===plan.color?0:1;if(ca!==cb)return ca-cb;const d=beadRegionScore(g,a,plan.region)-beadRegionScore(g,b,plan.region);return d||a-b;});return ids.slice(0,Math.min(beadTurnQuota(g),ids.length));}
function beadRolePlan(g){const counts={};for(const i of beadRoleCandidates(g))counts[g.target[i]]=(counts[g.target[i]]||0)+1;const colors=Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])),regions=['中央','左上','右上','左下','右下','边缘'];return{color:colors.length?colors[(Math.max(1,g.round)-1)%Math.min(3,colors.length)][0]:'',region:regions[(Math.max(1,g.round)-1)%regions.length],say:''};}
async function beadRoleTurn(g){
  if(!g||_bead!==g||g.phase!=='play'||g.ready||g.turn!=='ta'||g.busy)return;g.busy=true;g.status=beadRoleName(g)+' 正在看图纸选择这一轮。';beadSave(g);render();const token=++_beadDrawToken,plan=await beadRolePlan(g);if(_bead!==g||token!==_beadDrawToken||g.phase!=='play')return;const ids=beadChooseRoleCells(g,plan);if(!ids.length)return beadReady(g);
  for(let n=0;n<ids.length;n++){if(_bead!==g||token!==_beadDrawToken||g.phase!=='play')return;const i=ids[n];g.board[i]=g.target[i];g.owners[i]='ta';g.status=beadRoleName(g)+' 已正确填入 '+(n+1)+'/'+ids.length+' 格。';beadDraw();beadUpdateHUD();await new Promise(r=>setTimeout(r,95));}
  beadAddHistory(g,'sys',beadRoleName(g)+' 完成了第 '+g.round+' 轮本地自动补位。',{round:g.round});
  g.busy=false;if(beadRemaining(g)===0)return beadReady(g);g.turn='me';g.turnPlaced=0;g.round++;g.status='轮到你了，这一轮可以填 '+beadTurnQuota(g)+' 格。';beadSave(g);render();if(g.demoRobot&&g.demoRunning)setTimeout(()=>beadDemoUserTurn(g),240);
}
async function beadDemoUserTurn(g){if(!g||_bead!==g||g.phase!=='play'||g.ready||g.turn!=='me'||!g.demoRunning)return;const left=Math.max(0,beadTurnQuota(g)-g.turnPlaced),ids=beadChooseRoleCells(g,{color:'',region:'任意'}).slice(0,left);for(let n=0;n<ids.length;n++){if(_bead!==g||!g.demoRunning||g.phase!=='play')return;const i=ids[n];g.board[i]=g.target[i];g.owners[i]='me';g.turnPlaced++;g.status='模拟玩家已正确填入 '+g.turnPlaced+'/'+beadTurnQuota(g)+' 格。';beadDraw();beadUpdateHUD();await new Promise(r=>setTimeout(r,75));if(beadRemaining(g)===0)return beadReady(g);}if(g.turnPlaced>=beadTurnQuota(g)||!beadRemaining(g)){g.turn='ta';g.turnPlaced=0;g.status='轮到自动机器人补位。';beadSave(g);render();setTimeout(()=>beadRoleTurn(g),180);}}
function beadToggleDemo(){const g=_bead;if(!g||!g.demoRobot||g.phase!=='play'||g.ready)return;g.demoRunning=!g.demoRunning;g.status=g.demoRunning?'自动演示已继续。':'自动演示已暂停。';beadSave(g);render();if(g.demoRunning){if(g.turn==='ta')setTimeout(()=>beadRoleTurn(g),120);else setTimeout(()=>beadDemoUserTurn(g),120);}}
