async function beadRoleFinishAll(){const g=_bead;if(!g||g.phase!=='play'||g.ready||g.busy)return;const remaining=beadRemaining(g);if(!remaining)return beadReady(g);if(typeof uiConfirm==='function'&&!await uiConfirm('让 '+beadRoleName(g)+' 把剩余 '+remaining+' 格全部正确拼好？'))return;g.busy=true;g.status=beadRoleName(g)+' 正在完成剩余 '+remaining+' 格。';beadSave(g);render();await new Promise(r=>setTimeout(r,80));if(_bead!==g||g.phase!=='play')return;for(let i=0;i<g.target.length;i++)if(g.target[i]&&!g.board[i]){g.board[i]=g.target[i];g.owners[i]='ta';}beadAddHistory(g,'sys',beadRoleName(g)+' 按锁定图纸正确补完了剩余 '+remaining+' 格。');beadReady(g);setTimeout(()=>{if(_bead===g&&g.ready)beadFinishOpen(true);},120);}
function beadFinishOpen(exitAfter){const g=_bead;if(!g||!g.ready)return;_beadFinishExitAfter=!!exitAfter;openModal(`<h3>给作品起个名字</h3><div class="hint">确认后会自动归档完整成品，${esc(beadRoleName(g))} 会根据作品信息和自己的人设在微信里发来一条消息。</div><input id="beadWorkName" maxlength="60" value="${esc(g.workName||beadTitle(g))}" placeholder="作品名字"><div class="btns"><button class="btn g" onclick="beadFinishCancel()">再看看</button><button class="btn p" onclick="beadConfirmFinish()">完成并保存</button></div>`);setTimeout(()=>{const el=document.getElementById('beadWorkName');if(el){el.focus();el.select();}},80);}
function beadFinishCancel(){_beadFinishExitAfter=false;closeModal();}
function beadConfirmFinish(){const g=_bead;if(!g||!g.ready)return;const el=document.getElementById('beadWorkName'),name=String(el&&el.value||'').trim().slice(0,60),exitAfter=_beadFinishExitAfter;_beadFinishExitAfter=false;if(!name){toast('先给作品起一个名字');return;}closeModal();beadComplete(g,name,exitAfter);}
function beadContribution(g){const owners=Array.isArray(g&&g.owners)?g.owners:[],me=owners.reduce((n,x)=>n+(x==='me'?1:0),0),ta=owners.reduce((n,x)=>n+(x==='ta'?1:0),0),saved=g&&g.collaboration&&typeof g.collaboration==='object'?g.collaboration:{};return{meName:String(saved.meName||beadMeName()),roleName:String(saved.roleName||beadRoleName(g)),meCells:Number.isFinite(+saved.meCells)?+saved.meCells:me,roleCells:Number.isFinite(+saved.roleCells)?+saved.roleCells:ta};}
function beadArtworkFacts(g){const counts=Object.entries(beadColorCounts(g)).sort((a,b)=>b[1]-a[1]),palette=counts.slice(0,6).map(x=>beadColorName(x[0])+' '+x[1]+'格').join('、'),t=beadContribution(g);return '这是你（'+t.roleName+'）和'+t.meName+'共同完成并保存的协作画作；'+t.meName+'实际填了 '+t.meCells+' 格，你实际填了 '+t.roleCells+' 格。作品名《'+g.workName+'》，原图名称“'+(g.sourceName||'未命名图片')+'”，尺寸 '+g.cols+'×'+g.rows+'，共 '+beadTotal(g)+' 个目标格'+(palette?'，主要颜色是'+palette:'')+'。';}
function beadQueueCompletionMessage(g){if(!g||g.phase!=='done'||g.completionMessaged||typeof scheduleReply!=='function')return false;const c=getC(g.cid);if(!c||c.blocked)return false;const facts=beadArtworkFacts(g),detail='你刚刚在“像素拼拼乐”完成并保存了一幅真实作品。'+facts+'请把它明确当成你和用户一起参与完成的作品，结合这幅作品的信息、你自己的完整人设、你和ta的关系以及当下感受，在微信里主动发一条自然消息；可以评价画面和配色、说一起完成的感受或约下一幅，但不能假装看见这里没有提供的画面细节，不要复述系统说明，不要冒充ta说话。',note=typeof featureEventNote==='function'?featureEventNote('像素作品完成',detail):'[系统：'+detail+']',queued=scheduleReply(g.cid,note);if(queued){g.completionMessaged=true;g.completionMessageQueuedAt=Date.now();beadSave(g);}return !!queued;}
