function beadGalleryCount(){return beadStore().works.filter(x=>x&&x.archiveId).length;}
function beadGalleryItemsHTML(){let migrated=false;const html=beadStore().works.filter(x=>x&&x.archiveId).sort((a,b)=>(b.completedAt||0)-(a.completedAt||0)).map(x=>{const when=typeof ymd==='function'?ymd(x.completedAt||Date.now()):new Date(x.completedAt||Date.now()).toLocaleDateString(),t=beadContribution(x),src=x.previewSrc||beadThumbnailData(x);if(src&&!x.previewSrc){x.previewSrc=src;migrated=true;}const preview=src?`<img src="${esc(src)}" alt="${esc(x.workName||'像素作品')}" onclick="event.stopPropagation();beadOpenSaved('${x.archiveId}')">`:`<span class="bead-gallery-thumb" onclick="event.stopPropagation();beadOpenSaved('${x.archiveId}')">${gameLineIcon('beads')}</span>`;return `<article>${preview}<div onclick="beadOpenSaved('${x.archiveId}')"><b>${esc(x.workName||'未命名像素作品')}</b><small>${esc(t.meName)} 与 ${esc(t.roleName)} 共同完成 · ${esc(when)}</small></div><button onclick="beadDeleteArtwork('${x.archiveId}')">删除</button></article>`;}).join('');if(migrated)save();return html;}
async function beadDeleteArtwork(archiveId){if(typeof uiConfirm==='function'&&!await uiConfirm('删除这幅已经保存的像素作品？'))return;const box=beadStore();box.works=box.works.filter(x=>x&&x.archiveId!==archiveId);save();if(typeof dgOpenGallery==='function')dgOpenGallery();}
function beadComplete(g,name,exitAfter){
  if(!g||g.phase==='done')return;g.workName=String(name||beadTitle(g)||'像素作品').trim().slice(0,60);g.phase='done';g.ready=false;g.busy=false;g.turnPlaced=0;g.completedAt=Date.now();g.status='作品“'+g.workName+'”已自动保存。';g.collaboration=beadContribution(g);beadAddHistory(g,'sys','最后一格完成，你和'+beadRoleName(g)+'共同拼好了“'+g.workName+'”。');g.archiveId='work_'+uid();const box=beadStore(),snapshot={archiveId:g.archiveId,id:g.id,cid:g.cid,cols:g.cols,rows:g.rows,detail:g.detail,turnQuota:g.turnQuota,phase:'done',template:'image',target:g.target.slice(),owners:g.owners.slice(),selected:g.selected,workName:g.workName,sourceName:g.sourceName,completedAt:g.completedAt,status:g.status,collaboration:Object.assign({},g.collaboration),previewSrc:beadThumbnailData(g)};box.works=box.works.filter(x=>x&&x.archiveId!==snapshot.archiveId);box.works.push(snapshot);if(box.works.length>10)box.works=box.works.slice(-10);beadSave(g);
  try{gameSetHandoff(g.cid,'像素拼拼乐',(g.history||[]).map(x=>({who:x.who==='ta'?'ta':'sys',name:x.who==='ta'?beadRoleName(g):'游戏事件',text:x.text})));}catch(_){}render();beadQueueCompletionMessage(g);if(exitAfter)beadExit();
}
function beadDownload(){const g=_bead;if(!g)return;const size=g.cols>96?14:g.cols>64?17:22,pad=28,out=document.createElement('canvas');out.width=g.cols*size+pad*2;out.height=g.rows*size+pad*2;const ctx=out.getContext('2d');ctx.fillStyle='#f6f1e7';ctx.fillRect(0,0,out.width,out.height);ctx.textAlign='center';ctx.textBaseline='middle';for(let y=0;y<g.rows;y++)for(let x=0;x<g.cols;x++){const color=g.target[y*g.cols+x],px=pad+x*size,py=pad+y*size;ctx.fillStyle=color||'#fbf9f3';ctx.fillRect(px,py,size,size);if(color&&size>=17){const rgb=beadHexRgb(color),light=rgb[0]*.299+rgb[1]*.587+rgb[2]*.114;ctx.fillStyle=light<132?'rgba(255,255,255,.88)':'rgba(35,30,29,.72)';ctx.font=`${Math.max(6,size*.34)}px monospace`;ctx.fillText(beadColorCode(color),px+size/2,py+size/2);}ctx.strokeStyle=x%5===0||y%5===0?'rgba(52,184,174,.46)':'rgba(72,64,60,.20)';ctx.lineWidth=x%5===0||y%5===0?1:.45;ctx.strokeRect(px,py,size,size);}ctx.fillStyle='#50463f';ctx.font='9px system-ui';for(let x=0;x<g.cols;x+=5){ctx.fillText(String(x+1),pad+x*size+size/2,14);ctx.fillText(String(x+1),pad+x*size+size/2,out.height-12);}for(let y=0;y<g.rows;y+=5){ctx.fillText(String(y+1),13,pad+y*size+size/2);ctx.fillText(String(y+1),out.width-13,pad+y*size+size/2);}const a=document.createElement('a'),name=(g.workName||g.sourceName||g.cols+'x'+g.rows).replace(/[\\/:*?"<>|]/g,'-');a.download='像素拼拼乐-'+name+'-'+Date.now()+'.png';a.href=out.toDataURL('image/png');a.click();}

