const swipeStyle=document.createElement('style');swipeStyle.textContent='.bead-dock .bead-palette{touch-action:pan-x;overscroll-behavior-x:contain}.bead-nav{position:relative;grid-template-columns:42px 1fr 74px}.bead-nav>div{position:absolute;left:50%;width:190px;transform:translateX(-50%);text-align:center;pointer-events:none}.bead-nav>div b{font-size:16px}.bead-readybar{height:58px;box-sizing:border-box;display:flex;align-items:center;gap:8px;padding:7px 10px}.bead-readybar>div{min-width:0;flex:1}.bead-readybar b,.bead-readybar span{display:block}.bead-readybar b{font-size:10px}.bead-readybar span{margin-top:3px;color:#8e8580;font-size:7px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bead-readybar button{height:39px;padding:0 14px;border:1px solid #c69b68;border-radius:11px;background:linear-gradient(135deg,#e0bf92,#b7814f);color:#23170f;font-size:9px;font-weight:700}';document.head.appendChild(swipeStyle);

try{if(typeof NORTH_PREVIEW_PARAMS==='string'&&NORTH_PREVIEW_PARAMS.includes('bead-studio')){const openPreview=()=>{if(window.__northBootReady===true&&typeof getC==='function'&&getC('preview_1')){_bead=beadFresh('preview_1',32,32);stack=[{p:'beadstudio'}];render();const p=new URLSearchParams(location.search),sample=p.get('beadSample');if(sample)setTimeout(()=>beadPreviewImportUrl(sample,p.get('beadDetail')||64),80);if(p.get('beadRobot')==='1')setTimeout(()=>{if(!_bead||_bead.phase!=='design')return;_bead.demoRobot=true;_bead.demoRunning=true;beadLock();setTimeout(()=>beadDemoUserTurn(_bead),220);},sample?650:120);return true;}return false;};if(!openPreview()){const timer=setInterval(()=>{if(openPreview())clearInterval(timer);},60);setTimeout(()=>clearInterval(timer),5000);}}}catch(e){console.warn('像素拼拼乐预览初始化失败',e);}
